//! 🧪️ A staged native array projection retains its actual Source and finite Work bank.
use semio_framework_value_snapshot_projection::snapshot_projection::ArrayProjection;
use semio_framework_value_retained_clone::*;
use semio_framework_value_clone_source_testing::{FixtureSourceBirth,FixtureCloseStep};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
use std::mem::ManuallyDrop;
type Root=[u8;8192];
#[derive(Clone,Copy,PartialEq,Eq)]enum Op{Advance,Start,Close}
struct Context<'a>{source:RetainedCloneRef<'a,Root>,turn:OriginalSourceTurnIdentity,op:Op,body:usize,maximum:u64}
struct Producer{field:ManuallyDrop<ArrayProjection<u8,8192>>,source:(u64,usize,usize,usize),turn:OriginalSourceTurnIdentity,selected:Option<(OriginalEffectInvocationIdentity,Op,usize,u64)>}
impl Producer{fn empty(&self)->bool{self.selected.is_none()&&self.field.terminal_is_empty()}fn dispatch<'r>(&mut self,c:&mut Context<'_>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>,recover:bool)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{let invocation=effect.invocation().ok_or_else(||ValueError::invariant("field law invocation absent"))?;let mode=if recover{OriginalEffectCallbackMode::Recover}else{OriginalEffectCallbackMode::Receive};if invocation.mode()!=mode{return Err(ValueError::invariant("field law invocation changed"))}let key=(invocation.identity(),c.op,c.body,c.maximum);if recover{if self.selected!=Some(key){return Err(ValueError::invariant("field law request changed"))}}else if self.selected.is_some(){return Err(ValueError::invariant("field law action occupied"))}let mut scope=reply.scope(&mut self.selected,key)?;let done=match(c.op,recover){(Op::Advance,false)=>self.field.advance_into(c.source,c.body,c.maximum,effect,scope.borrow()?)?,(Op::Advance,true)=>self.field.recover_advance_into(c.source,c.body,c.maximum,effect,scope.borrow()?)?,(Op::Start,false)=>self.field.begin_close_into(effect,scope.borrow()?)?,(Op::Start,true)=>self.field.recover_begin_close_into(effect,scope.borrow()?)?,(Op::Close,false)=>self.field.close_into(c.body,effect,scope.borrow()?)?,(Op::Close,true)=>self.field.recover_close_into(c.body,effect,scope.borrow()?)?};drop(done);Ok(scope.forwarded())}}
impl Drop for Producer{fn drop(&mut self){if std::thread::panicking(){return}assert!(self.empty());unsafe{ManuallyDrop::drop(&mut self.field)}}}
impl OriginalEffectProducer for Producer{type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=Context<'a> where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{if c.source.reference_identity()!=self.source||c.turn!=self.turn{return Err(ValueError::invariant("field law changed original Source"))}Ok(())}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.turn)}fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.dispatch(c,e,r,false)}fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.dispatch(c,e,r,true)}}
fn grant_for(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[test]fn staged_array_projection_copies_and_cancels_in_bounded_original_turns(){let law:serde_json::Value=serde_json::from_str(include_str!("array-projection.json")).unwrap();assert_eq!(law["length"].as_u64().unwrap(),8192);let mut source=RetainedCloneSource::<Root>::from_owner([law["value"].as_u64().unwrap() as u8;8192]);let id=source.borrow().reference_identity();let pointer=source.borrow().get().as_ptr();let mut authority=None;source.with_bank(|_,bank|{let(poll,actual)=bank.run_with_source(RetainedCloneGrant::default(),0,|_,witness|{authority=Some(OriginalEffectAuthority::new(Producer{field:ManuallyDrop::new(ArrayProjection::new()),source:id,turn:witness.identity(),selected:None}));RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:0})});assert!(matches!(poll,RetainedWorkPoll::Complete(_)));assert!(actual.is_none())}).unwrap();let mut action=None;let mut answer=None;let mut op=Op::Advance;for _ in 0..2048{let p=authority.as_ref().unwrap();if op==Op::Advance&&p.inspect(|p|p.field.ready()){op=Op::Start}if op==Op::Close&&p.inspect(Producer::empty){break}let(d,work)=source.with_bank(|original,_|p.inspect(|p|match op{Op::Advance=>(p.field.demands(original,4096,4096).unwrap(),p.field.advance_work_demand(original,4096,4096).unwrap()),Op::Start=>(p.field.begin_close_demand().unwrap(),p.field.begin_close_work_demand().unwrap()),Op::Close=>{assert!(!p.field.requires_original_birth());assert!(!p.field.requires_original_control());(p.field.close_demands(4096).unwrap(),p.field.close_work_demand(4096).unwrap())}})).unwrap();let((poll,actual),heap)=source.with_bank(|original,bank|{let grant=grant_for(d);assert!(d.copy_bytes<=law["maximumCopy"].as_u64().unwrap() as usize);assert!(work<=law["maximumWork"].as_u64().unwrap());let observed=observe(||bank.run_with_source(grant,work,|effect,witness|{let before=effect.performed_work();let mut context=Context{source:original,turn:witness.identity(),op,body:4096,maximum:4096};let ready=authority.as_mut().unwrap().drive(&mut context,effect,&mut action).unwrap();let work=effect.performed_work()-before;if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work})}else{RetainedWorkPoll::Pending{work}}}));if let(RetainedWorkPoll::Complete(_),_)=&observed.0{assert!(action.as_mut().unwrap().transfer_reply(&mut answer).unwrap());authority.as_mut().unwrap().finish(&mut action).unwrap();let step=answer.as_ref().unwrap().as_ref().unwrap();assert_eq!(observed.1,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert_ne!(bank.take_admitted(),Some(false));bank.post(step.progress(),grant,observed.1)}observed}).unwrap();assert!(matches!(poll,RetainedWorkPoll::Complete(_)));if let Some(actual)=actual{assert_eq!(actual,heap.0)}answer.take().unwrap().unwrap();assert_eq!(source.borrow().get().as_ptr(),pointer);if op==Op::Start{op=Op::Close}}assert!(authority.as_ref().unwrap().inspect(Producer::empty));
 source.with_bank(|original,bank|{let d=OriginalEffectAuthority::<Producer>::producer_transfer_demand().unwrap();let grant=grant_for(d);let mut producer=None;let((poll,_),heap)=observe(||bank.run_with_source(grant,1,|effect,witness|{let context=Context{source:original,turn:witness.identity(),op:Op::Close,body:0,maximum:0};RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&context,&mut producer,effect))}));let RetainedWorkPoll::Complete(done)=poll else{panic!("producer transfer pending")};let progress=done.result.unwrap().unwrap();assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,heap);let witness=unsafe{RetainedCursorRelease::native(Producer::empty)};let d=witness.inline_demand();let grant=grant_for(d);let mut reply=None;let((poll,_),heap)=observe(||bank.run(grant,1,|effect|{let before=effect.performed_work();drop(witness.inline_into(&mut producer,effect,OriginalEffectReply::borrow(&mut reply).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));assert!(matches!(poll,RetainedWorkPoll::Complete(_)));let step=reply.take().unwrap().unwrap();assert_eq!(bank.take_admitted(),Some(true));bank.post(step.progress(),grant,heap)}).unwrap();for _ in 0..10000{if source.terminal_is_empty(){break}match source.close_once().unwrap(){FixtureCloseStep::Denied|FixtureCloseStep::Blocked=>panic!("source close refused"),_=>{}}}assert!(source.terminal_is_empty());}
